{
  "findings": [
    {
      "check_id": "CKV_GCP_102",
      "title": "Ensure that GCP Cloud Run services are not anonymously or publicly accessible",
      "resource": "google_cloud_run_service_iam_binding.search_service_public",
      "severity": "MEDIUM",
      "explanation": "The IAM binding grants the 'roles/run.invoker' role to 'allUsers', making the Cloud Run service publicly accessible. This can expose sensitive data or functionality to unauthorized users."
    }
  ],
  "patched_code": "resource \"google_cloud_run_service_iam_binding\" \"search_service_public\" {\n  location = google_cloud_run_service.search_service.location\n  project  = google_cloud_run_service.search_service.project\n  service  = google_cloud_run_service.search_service.name\n  role     = \"roles/run.invoker\"\n  members = [\n    \"group:authorized-users@example.com\", # Replace with a specific group or user\n  ]\n}",
  "fix_summary": "Replaced 'allUsers' with a specific group or user to restrict access to the Cloud Run service, ensuring it is not publicly accessible."
}
